<script setup>
import {ref,reactive,computed,onMounted,nextTick} from 'vue';import MenuIcon from './MenuIcon.vue';import ConsoleDetails from './ConsoleDetails.vue';import wallets from '../../PackageFlow.Windows/Assets/donations.json';
const state=ref({language:'ru',version:'1.10.17',wizard:false,busy:false,components:{},config:{},lan:[],found:[],consoles:null,log:[],progress:0,started:false});
const page=ref('home'),step=ref(0),wizard=ref(false),done=ref(false),error=ref(''),dialog=ref(null),qr=ref(null),advanced=ref(''),showPassword=ref(false),selected=ref(''),checked=ref([]),scan=ref(false),windowsUpdate=ref(false);
const draft=reactive({hostIp:'',port:3000,payloadPort:3001,autoStart:false,visibleBrowser:true,prowlarrUrl:'http://127.0.0.1:9696',prowlarrKey:'',trackerUsername:'',trackerPassword:'',torrentAddress:'http://127.0.0.1:8080',torrentUser:'',torrentPassword:'',torrentFolder:'',installFlare:true,indexerId:0});
const migrationPath=ref(''),migrationEmpty=ref(false);
const choice=reactive({consoles:true,torrents:false,ips:[],manual:false});const manual=reactive({ip:'',name:'',platform:'ps5'});let initialized=false;const pending=new Map();let serial=0;
const en=computed(()=>state.value.language==='en');const t=(ru,eng)=>en.value?eng:ru;
const nav=computed(()=>[['home',t('Главная','Home')],['consoles',t('Приставки','Consoles')],['search',t('Поиск','Search')],['updates',t('Обновления','Updates')],['support',t('Поддержать проект','Support the project')]]);
const consoles=computed(()=>state.value.consoles?.consoles||[]);const found=computed(()=>state.value.found||[]);
const selectedConsole=computed(()=>consoles.value.find(c=>c.id===selected.value));
const logo=name=>`assets/${({qBittorrent:'qbittorrent',Prowlarr:'prowlarr',FlareSolverr:'flaresolverr',RuTracker:'rutracker'})[name]||name}.svg`;
function receive(message){if(message.type==='state'){state.value=message;if(message.consoles?.consoles?.length&&!message.consoles.consoles.some(c=>c.id===selected.value))selected.value=message.config.consoleId||message.consoles.consoles[0].id;if(!migrationPath.value&&message.migration?.review?.SuggestedDirectory)migrationPath.value=message.migration.review.SuggestedDirectory;if(!initialized){Object.assign(draft,message.config);wizard.value=message.wizard;initialized=true;selected.value=message.config.consoleId||message.consoles?.consoles?.[0]?.id||'';}else if(!message.busy){if(!draft.trackerUsername)draft.trackerUsername=message.config.trackerUsername||'';draft.torrentAddress=message.config.torrentAddress||draft.torrentAddress;draft.torrentUser=message.config.torrentUser||draft.torrentUser;}}else if(message.type==='dialog'){dialog.value=message;nextTick(()=>document.querySelector('.dialog .keep')?.focus());}else if(message.type==='wizard'){wizard.value=true;step.value=0;done.value=false;}else if(message.type==='result'){const p=pending.get(message.id);pending.delete(message.id);message.ok?p?.resolve():p?.reject(new Error(message.error));}}
function send(command,payload={}){if(!window.chrome?.webview){error.value=t('Предпросмотр UI: команды доступны в Windows WebView2.','UI preview: commands are available in Windows WebView2.');return Promise.reject(new Error(error.value));}const id=String(++serial);return new Promise((resolve,reject)=>{pending.set(id,{resolve,reject});window.chrome.webview.postMessage({id,command,payload});});}
async function run(command,payload={}){error.value='';try{await send(command,payload);return true;}catch(e){error.value=e.message;return false;}}
function fields(){const p={...draft};p.port=Number(p.port);p.payloadPort=Number(p.payloadPort);p.indexerId=Number(p.indexerId);delete p.gamesDirectory;delete p.consoleId;delete p.torrents;delete p.automaticSetupPending;delete p.trackerPasswordSaved;delete p.prowlarrKeySaved;for(const key of ['prowlarrKey','trackerPassword','torrentPassword'])if(!p[key])delete p[key];if(!p.hostIp)delete p.hostIp;return p;}
async function openWeb(){if(!state.value.started&&!await run('apply',fields()))return;await run('web.open');}
async function action(command){await run(command,fields());for(const k of ['trackerPassword','torrentPassword','prowlarrKey'])draft[k]='';}
async function navigate(id){page.value=id;if(id==='consoles'||id==='updates')await run('refresh');}
async function discover(){scan.value=true;await run('discovery.start');scan.value=false;}
function dialogReply(confirmed){if(!dialog.value)return;send('dialog.reply',{dialogId:dialog.value.id,confirmed}).catch(()=>{});dialog.value=null;}
function keyboard(e){if(dialog.value&&e.key==='Tab'){const buttons=[...document.querySelectorAll('.dialog button')];const i=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();return;}if(dialog.value&&(e.key==='Escape'||e.key==='Enter'&&e.target?.classList?.contains('keep'))){e.preventDefault();dialogReply(false);}if(qr.value&&e.key==='Escape')qr.value=null;}
async function finish(){done.value=false;const ok=await run('wizard.finish',{torrents:choice.torrents,consoles:choice.consoles?choice.ips:[],trackerUsername:draft.trackerUsername,trackerPassword:draft.trackerPassword,manual:choice.manual});draft.trackerPassword='';done.value=ok;}
function next(){if(step.value===0){step.value=choice.consoles?1:choice.torrents?2:3;}else if(step.value===1)step.value=choice.torrents?2:3;else step.value=3;}
function selectConsole(id){selected.value=id;if(!state.value.busy)run('console.select',{id});}
function mark(id){checked.value=checked.value.includes(id)?checked.value.filter(x=>x!==id):[...checked.value,id];}
const allChecked=computed(()=>consoles.value.length>0&&consoles.value.every(c=>checked.value.includes(c.id)));
function markAll(on){checked.value=on?consoles.value.map(c=>c.id):[];}
// «Удалить профиль» removes the checked consoles; without a check, the highlighted one.
const forgetIds=computed(()=>checked.value.length?checked.value:selected.value?[selected.value]:[]);
async function forgetChecked(){const ids=[...forgetIds.value];for(const id of ids){if(!await run('console.forget',{id}))break;checked.value=checked.value.filter(x=>x!==id);}}
const gib=v=>Number.isFinite(v)&&v>=0?(v/1024**3).toLocaleString(en.value?'en-US':'ru-RU',{maximumFractionDigits:1}):'—';
const shortBuild=b=>typeof b==='string'?b.replace(/^ps5-service-pkg-context-/,''):'';
function appVersion(c){const u=state.value.updates?.[c.id]||{};return c.platform==='ps5'?(u.appInstalled===false?t('Не установлено','Not installed'):u.appCurrent||'—'):c.pkgVersion||'—';}
async function connect(ip=manual.ip,name=manual.name,platform=manual.platform){await run('console.connect',{ip,name:name||platform.toUpperCase(),platform});}
async function install(){const ids=checked.value.length?checked.value:selected.value?[selected.value]:[];if(!ids.length){error.value=t('Выберите приставки','Select consoles');return;}await run('console.install',{ids});}
async function findInstall(){await discover();for(const d of found.value)if(!consoles.value.some(c=>c.ip===d.Ip))await connect(d.Ip,d.Name,d.Platform);checked.value=consoles.value.filter(c=>found.value.some(d=>d.Ip===c.ip)).map(c=>c.id);await install();}
const preview=new URLSearchParams(location.search);onMounted(()=>{window.addEventListener('keydown',keyboard);if(window.chrome?.webview){window.chrome.webview.addEventListener('message',e=>receive(e.data));send('ready').catch(()=>{});}else{initialized=true;if(preview.has('preview')){wizard.value=preview.get('preview')==='wizard';page.value=preview.get('preview')==='wizard'?'home':preview.get('preview');state.value.status='UI preview · isolated fixture / изолированная фикстура';}}});
</script>
<template>
<div class="shell" :class="{wizard}">
<header><img class="brand" :src="`assets/packageflow-${en?'en':'ru'}.svg`" alt="PackageFlow"/><div v-if="wizard" class="steps"><div v-for="(label,i) in [t('Выбор','Select'),t('Приставки','Consoles'),t('Торренты','Torrents'),t('Готово','Ready')]" :key="i" :class="{active:i===step,passed:i<step}"><b>{{i<step?'✓':i+1}}</b><small>{{label}}</small></div></div><div class="header-links"><button class="community-link discord-link" aria-label="Discord" title="Discord" @click="run('link',{target:'discord'})"><svg width="27" height="27" viewBox="0 0 28 28" aria-hidden="true"><path fill="currentColor" d="M7 5.5 11 4l.8 1.8a21 21 0 0 1 4.4 0L17 4l4 1.5c2.4 3.5 3.8 7.4 4 11.7-2 1.6-4.2 2.6-6.5 3.3l-1.1-2.1 2.4-1.1c-3.7 1.7-7.9 1.7-11.6 0l2.4 1.1-1.1 2.1A21 21 0 0 1 3 17.2C3.2 12.9 4.6 9 7 5.5Z"/><ellipse cx="10" cy="12.8" rx="1.6" ry="2" fill="#0a2445"/><ellipse cx="18" cy="12.8" rx="1.6" ry="2" fill="#0a2445"/></svg><span>Discord</span></button><button class="community-link github-link" @click="run('link',{target:'github'})"><img src="assets/github.svg" alt=""/>GitHub</button><button class="community-link fourpda-link" aria-label="4PDA" title="4PDA" @click="run('link',{target:'4pda'})"><img class="fourpda-mark" src="assets/4pda.png" alt="4PDA"/></button><button :class="{active:!en}" @click="run('language',{language:'ru'})">RU</button><button :class="{active:en}" @click="run('language',{language:'en'})">EN</button></div></header>
<div v-if="!wizard" class="health"><span v-for="name in ['WEB','qBittorrent','Prowlarr','FlareSolverr']" :key="name"><i :class="{ready:state.components[name]?.ready}"></i>{{name}} <small>{{!state.config.torrents&&name!=='WEB'&&!state.components[name]?.ready?t('Пропущен','Skipped'):state.components[name]?.state||t('Не проверен','Not checked')}}</small></span></div>
<div v-if="wizard" class="wizard-body">
<div class="wizard-heading"><h1>{{step===0?t('Добро пожаловать в PackageFlow','Welcome to PackageFlow'):step===1?t('Выберите PlayStation','Choose PlayStation'):step===2?t('Подключить RuTracker','Connect RuTracker'):t('Подготовка PackageFlow','Prepare PackageFlow')}}</h1><p>{{step===0?t('Выберите, что настроить','Choose what to configure'):step===1?t('Найдите приставки в локальной сети или укажите IP','Find consoles on your local network or enter an IP'):step===2?t('Войдите в аккаунт или настройте поиск позже','Sign in or set up search later'):t('Проверьте выбранное перед началом установки','Review your choices before installation')}}</p></div>
<div v-if="step===0" class="choice-grid"><label class="choice glass" :class="{selected:choice.consoles}"><input type="checkbox" v-model="choice.consoles"/><img class="console-art" src="assets/consoles.png" alt="PlayStation 5 and PlayStation 4"/><h2>{{t('Найти PlayStation','Find PlayStation')}}</h2><p>{{t('Найти приставки и подготовить компоненты','Find consoles and prepare components')}}</p></label><label class="choice glass" :class="{selected:choice.torrents}"><input type="checkbox" v-model="choice.torrents"/><div class="search-art"><svg viewBox="0 0 300 130" aria-hidden="true"><defs><linearGradient id="orb"><stop stop-color="#05d8ff"/><stop offset="1" stop-color="#7142ff"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="4"/></filter></defs><ellipse cx="150" cy="105" rx="116" ry="18" fill="#19bafa" opacity=".25" filter="url(#glow)"/><circle cx="211" cy="55" r="40" fill="url(#orb)" stroke="#bdeeff" stroke-width="2"/><path d="M211 31v36m-14-14 14 15 14-15m-34 24h41" stroke="white" stroke-width="6" fill="none" stroke-linecap="round"/><circle cx="79" cy="48" r="31" fill="#072144" stroke="#d5f4ff" stroke-width="7"/><path d="m102 71 32 31" stroke="#8dadce" stroke-width="13" stroke-linecap="round"/><circle cx="79" cy="48" r="25" fill="#11acff" opacity=".14"/></svg><div class="logo-row"><img src="assets/rutracker.ico" alt="RuTracker"/><img v-for="name in ['qBittorrent','Prowlarr','FlareSolverr']" :src="logo(name)" :alt="name"/></div></div><h2>{{t('Торренты и поиск','Torrents and search')}}</h2><p>RuTracker · qBittorrent · Prowlarr · FlareSolverr</p></label></div>
<div v-if="step===0" class="hint">ⓘ {{t('Без торрентов связанные компоненты не устанавливаются','Torrent components are only installed when selected')}}</div>
<div v-if="step===1" class="wizard-console glass"><div class="actions"><button class="primary" :disabled="scan" @click="discover">{{t('Найти в сети','Find on network')}}</button><button v-if="scan" @click="run('discovery.cancel')">{{t('Отменить поиск','Cancel search')}}</button><span>{{scan?t('Поиск…','Searching…'):t('Установка начнётся после итогового подтверждения','Installation starts after final confirmation')}}</span></div><div class="discovered"><label v-for="d in found" :key="d.Ip" class="console-row"><input type="checkbox" v-model="choice.ips" :value="d.Ip"/><b>{{d.Platform.toUpperCase()}} · {{d.Name}}</b><span>{{d.Ip}}</span><small>{{d.Service?t('Служба онлайн','Service online'):t('Неизвестно','Unknown')}}</small></label><p v-if="!found.length">{{t('Пока ничего не найдено','No consoles discovered yet')}}</p></div><div class="manual-grid"><label>IP<input v-model="manual.ip" placeholder="192.168.1…"/></label><label>{{t('Название','Name')}}<input v-model="manual.name"/></label><button :disabled="state.busy" @click="run('discovery.manual',{ip:manual.ip})">{{t('Проверить IP','Check IP')}}</button></div></div>
<div v-if="step===2" class="wizard-tracker glass"><div class="tracker-title"><img src="assets/rutracker.ico" alt="RuTracker"/><h2>RuTracker</h2></div><label>{{t('Логин','Username')}}<input v-model="draft.trackerUsername" autocomplete="off"/></label><label>{{t('Пароль','Password')}}<div class="password"><input v-model="draft.trackerPassword" :type="showPassword?'text':'password'" autocomplete="new-password"/><button @click="showPassword=!showPassword" :aria-label="t('Показать пароль','Show password')">◉</button></div></label><label class="check"><input type="checkbox" v-model="choice.manual"/>{{t('Войти через браузер после подготовки','Open manual browser sign-in after preparation')}}</label><p>{{t('При CAPTCHA откроется Chromium. Вход будет проверен отдельно. Пароль хранится защищённым в Windows.','CAPTCHA uses Chromium. Sign-in is verified separately. Windows protects the saved password.')}}</p></div>
<div v-if="step===3" class="wizard-ready"><div class="summary-grid"><article class="glass"><h2>♧ {{t('PlayStation','PlayStation')}}</h2><p>{{choice.consoles?`${choice.ips.length} ${t('выбрано','selected')}`:t('Пропущено','Skipped')}}</p><p v-for="ip in choice.ips">{{ip}}</p></article><article class="glass"><h2>↓ {{t('Торренты','Torrents')}}</h2><p>{{choice.torrents?'qBittorrent · Prowlarr · FlareSolverr':t('Пропущены','Skipped')}}</p><p>WEB · {{t('Локальный сервер','Local server')}}</p></article></div><article class="glass preparation"><h3>{{done?t('Подготовка завершена','Preparation complete'):state.busy?t('Подготавливаем компоненты…','Preparing components…'):t('Готово к настройке','Ready to configure')}}</h3><progress :value="state.progress" max="100"/><p>{{state.status}}</p><div v-if="state.config.automaticSetupPending" class="hint">{{t('Подготовка компонентов требует внимания. Проверьте журнал и повторите в Поиске.','Component preparation needs attention. Check the log and retry in Search.')}}</div><div class="mini-log" v-if="state.log.length"><p v-for="line in state.log.slice(0,6)">{{line}}</p></div></article></div>
<div class="wizard-footer"><button v-if="step===0" :disabled="state.busy" @click="choice.consoles=false;choice.torrents=false;step=3">{{t('Пропустить','Skip')}}</button><button v-else :disabled="state.busy" @click="step--">← {{t('Назад','Back')}}</button><div class="actions"><button v-if="step===2" @click="choice.torrents=false;step=3">{{t('Пропустить торренты','Skip torrents')}}</button><button v-if="step<3" class="primary" :disabled="state.busy" @click="next">{{step===1?t('Подтвердить выбор','Confirm selection'):t('Продолжить','Continue')}} →</button><button v-else-if="done" class="primary" @click="wizard=false">{{t('Открыть управление','Open management')}} →</button><button v-else class="primary" :disabled="state.busy" @click="finish">{{state.busy?t('Подготовка…','Preparing…'):t('Настроить','Set up')}} →</button><button v-if="step===3&&!state.busy&&!done&&state.config.automaticSetupPending" @click="wizard=false;page='search'">{{t('Перейти к проверке','Review components')}}</button></div></div>
</div>
<div v-else class="workspace"><aside><button v-for="[id,label] in nav" :class="{active:page===id}" @click="navigate(id)"><span class="nav-symbol"><MenuIcon :name="id"/></span>{{label}}</button><div class="sidebar-bottom">Windows {{state.version}}<br/><small>{{t('Окно закрывается в трей','Closing minimizes to tray')}}</small></div></aside><main>
<section v-if="page==='home'"><article v-if="state.migration?.required" class="glass migration" role="alert"><h2>{{t('Перенос прежних данных WEB','Migrate previous WEB data')}}</h2><p>{{state.migration.review?.Message}}</p><p>{{t('Контейнерный запуск в Windows удалён. Программа не управляет прежним внешним сервером. Не выбирайте папку игр вместо папки данных.','Container startup has been removed from Windows. The app does not manage the former external server. Select WEB state data, not the games folder.')}}</p><label>{{t('Полный экспорт / прежний bind-каталог WEB','Complete export / former WEB bind directory')}}<input v-model="migrationPath"/></label><label v-if="state.migration.review?.EmptyBindAllowed" class="check"><input type="checkbox" v-model="migrationEmpty"/>{{t('Подтверждаю: обнаруженный bind-каталог пуст; переносить данных нет','Confirm: the detected bind directory is empty; there is no data to import')}}</label><div class="actions"><button :disabled="state.busy" @click="run('migration.inspect')">{{t('Проверить конфиг повторно','Review config again')}}</button><button class="primary" :disabled="state.busy||!migrationPath" @click="run('migration.confirm',{path:migrationPath,allowEmpty:migrationEmpty})">{{t('Создать копию для Windows','Create Windows data copy')}}</button></div></article><template v-if="!state.migration?.required"><div class="heading"><h1>{{t('Всё готово к работе','Ready to get started')}}</h1><p>{{t('Библиотека, установка и управление в PackageFlow','Library, installation and management in PackageFlow')}}</p></div><article class="glass home-hero"><div><p class="eyebrow">PACKAGEFLOW WEB</p><h2>{{state.started?t('Сервер запущен','Server running'):t('Запустите PackageFlow','Start PackageFlow')}}</h2><p>{{state.webUrl||'http://127.0.0.1:3000'}}</p></div><button class="primary open-web" :disabled="state.busy" @click="openWeb">◎ {{t('Открыть PackageFlow','Open PackageFlow')}} →</button></article><article class="glass server-settings"><h3>{{t('Параметры запуска','Launch settings')}}</h3><div class="field-grid"><label>{{t('IPv4 компьютера','Computer LAN IPv4')}}<select v-model="draft.hostIp"><option value="">{{t('Выберите адрес','Choose address')}}</option><option v-for="ip in state.lan">{{ip}}</option></select></label><label>{{t('Порт WEB','WEB port')}}<input type="number" v-model="draft.port" min="1024" max="65535"/></label><label>{{t('Порт PS4 → WEB','PS4 callback port')}}<input type="number" v-model="draft.payloadPort" min="1024" max="65535"/></label></div><div class="checks"><label><input type="checkbox" v-model="draft.autoStart"/>{{t('Автозапуск с Windows','Start with Windows')}}</label><label><input type="checkbox" v-model="draft.visibleBrowser"/>{{t('Видимый браузер Cloudflare','Visible Cloudflare browser')}}</label></div></article><div class="page-actions"><button class="primary" :disabled="state.busy" @click="action('apply')">{{t('Применить и запустить','Apply and start')}}</button><button :disabled="state.busy" @click="run('server.stop')">{{t('Остановить','Stop')}}</button><button @click="action('storage')">{{t('Хранилище в WEB','Storage in WEB')}}</button><button @click="action('firewall')">{{t('Доступ приставкам','Console access')}}</button><button @click="wizard=true;step=0;done=false">{{t('Мастер настройки','Setup wizard')}}</button></div></template></section>
<section v-if="page==='consoles'"><div class="heading"><h1>{{t('Приставки','Consoles')}}</h1><p>{{t('Сопряжение, проверка и установка на сохранённых PS4 / PS5','Pair, check and install on saved PS4 / PS5 consoles')}}</p></div><div class="page-actions console-actions"><button class="primary" :disabled="state.busy" @click="discover">{{t('Найти','Find')}}</button><button v-if="scan" @click="run('discovery.cancel')">{{t('Отменить поиск','Cancel discovery')}}</button><button :disabled="state.busy||!selected" @click="run('console.check',{id:selected})">{{t('Проверить','Check')}}</button><button :disabled="state.busy" @click="install">{{t('Установить / обновить','Install / update')}}</button><button :disabled="state.busy" @click="findInstall">{{t('Найти и установить','Find and install')}}</button><button :disabled="state.busy||!selected" @click="run('console.remove-app',{id:selected})">{{t('Удалить приложение','Remove app')}}</button><button :disabled="state.busy||!forgetIds.length" @click="forgetChecked">{{forgetIds.length>1?t('Удалить профили','Remove profiles')+' ('+forgetIds.length+')':t('Удалить профиль','Remove profile')}}</button><button :disabled="state.busy" @click="run('refresh')">⟳</button></div><details class="manual-connection" :open="!consoles.length"><summary>{{t('Добавить приставку по IP','Add console by IP')}}</summary><article class="glass"><div class="manual-grid"><label>IP<input v-model="manual.ip" placeholder="192.168.1…"/></label><label>{{t('Название','Name')}}<input v-model="manual.name"/></label><label>{{t('Платформа','Platform')}}<select v-model="manual.platform"><option value="ps5">PS5</option><option value="ps4">PS4</option></select></label><button class="primary" :disabled="state.busy" @click="connect()">{{t('Подключить','Connect')}}</button></div></article></details><article class="glass device-table-card"><table v-if="consoles.length" class="device-table"><thead><tr><th><input type="checkbox" :checked="allChecked" @change="markAll($event.target.checked)" :aria-label="t('Выбрать все','Select all')"/></th><th>{{t('Приставка','Console')}}</th><th>IP</th><th>{{t('Статус','Status')}}</th><th>{{t('Прошивка','Firmware')}}</th><th>{{t('Служба','Service')}}</th><th>{{t('Приложение','App')}}</th><th class="num">{{t('Свободно, GiB','Free, GiB')}}</th></tr></thead><tbody><template v-for="c in consoles" :key="c.id"><tr :class="{selected:selected===c.id}" @click="selectConsole(c.id)"><td @click.stop><input type="checkbox" :checked="checked.includes(c.id)" @change="mark(c.id)" :aria-label="t('Выбрать','Select')+' '+c.name"/></td><td><b>{{c.name}}</b> <span class="platform-tag">{{c.platform.toUpperCase()}}</span></td><td>{{c.ip}}</td><td><span class="status" :class="{online:c.online}"><i :class="{ready:c.online}"></i>{{c.online?t('В сети','Online'):c.restMode?t('В режиме покоя','Rest mode'):t('Нет связи','Offline')}}</span></td><td>{{c.firmware||'—'}}</td><td>{{c.version||'—'}}<small v-if="shortBuild(c.serviceBuild)">{{shortBuild(c.serviceBuild)}}</small></td><td>{{appVersion(c)}}</td><td class="num">{{gib(c.freeBytes)}}<small v-if="c.totalBytes"> / {{gib(c.totalBytes)}}</small></td></tr><tr v-if="selected===c.id" class="device-more"><td></td><td colspan="7"><ConsoleDetails compact :device="c" :update="state.updates?.[c.id]" :en="en"/></td></tr></template></tbody></table><p v-else class="empty">{{t('Сохранённых приставок пока нет','No saved consoles yet')}}</p><p v-if="consoles.length" class="table-hint">{{t('Галочка — для «Установить / обновить» и «Удалить профиль». Нажмите на строку, чтобы увидеть подробности.','Check consoles for “Install / update” and “Remove profile”. Click a row for details.')}}</p></article><article v-if="found.length" class="glass"><h3>{{t('Найдено в сети','Discovered on network')}}</h3><div v-for="d in found" class="console-row"><b>{{d.Platform.toUpperCase()}} · {{d.Name}}</b><span>{{d.Ip}}</span><small>{{d.Service?t('Служба онлайн','Service online'):t('Неизвестно','Unknown')}}</small><button :disabled="state.busy" @click="connect(d.Ip,d.Name,d.Platform)">{{t('Подключить','Connect')}}</button></div></article></section>
<section v-if="page==='search'" class="search-page"><div class="heading"><h1>{{t('Торренты и поиск','Torrents and search')}}</h1><p>{{t('Настройте источники, чтобы находить и загружать игры','Configure sources to find and download games')}}</p></div><article class="glass tracker-card"><div class="tracker-title"><img src="assets/rutracker.ico" alt="RuTracker"/><div><h2>RuTracker</h2><p>{{t('Вход проверяется через Prowlarr','Sign-in is verified through Prowlarr')}}</p></div></div><div class="tracker-fields"><label>{{t('Логин','Username')}}<input v-model="draft.trackerUsername" autocomplete="off"/></label><label>{{t('Пароль','Password')}}<div class="password"><input v-model="draft.trackerPassword" :type="showPassword?'text':'password'" :placeholder="state.config.trackerPasswordSaved?t('Сохранён в Windows','Saved in Windows'):''" autocomplete="new-password"/><button @click="showPassword=!showPassword" :aria-label="t('Показать пароль','Show password')">◉</button></div></label><div class="actions"><button class="primary" :disabled="state.busy" @click="action('tracker.test')">{{t('Подключить и проверить','Connect and test')}}</button><button :disabled="state.busy" @click="action('tracker.manual')">{{t('Войти через браузер','Browser sign-in')}}</button></div></div></article><div class="component-grid"><article v-for="(name,i) in ['qBittorrent','Prowlarr','FlareSolverr']" class="glass component"><div class="component-heading"><img :src="logo(name)" :alt="name"/><div><h3>{{name}}</h3><span class="status"><i :class="{ready:state.components[name]?.ready}"></i>{{!state.config.torrents&&!state.components[name]?.ready?t('Пропущен','Skipped'):state.components[name]?.state||t('Не настроен','Not configured')}}</span></div></div><p>{{i===0?t('Загрузка и хранение торрентов','Torrent downloads and storage'):i===1?t('Источники и индексаторы','Sources and indexers'):t('Авторизация через Chromium','Authentication with Chromium')}}</p><div class="actions"><button :disabled="state.busy" @click="action(i===0?'torrent.connect':i===1?'prowlarr.install':'flare.install')">{{i===0?t('Подключить','Connect'):t('Установить','Install')}}</button><button @click="advanced=advanced===name?'':name">{{t('Настроить','Configure')}} ⚙</button></div></article></div><div class="page-actions"><button class="primary" :disabled="state.busy" @click="action('torrent.setup')">{{state.config.automaticSetupPending?t('Повторить подготовку','Retry preparation'):t('Настроить торренты','Set up torrents')}}</button><button :disabled="state.busy" @click="action('setup.complete')">{{t('Открыть WEB','Open WEB')}}</button><button @click="advanced=advanced==='all'?'':'all'">{{t('Дополнительные параметры','Advanced settings')}}</button></div><article v-if="advanced" class="glass advanced"><h3>{{advanced==='all'?t('Дополнительные параметры','Advanced settings'):advanced}}</h3><div class="field-grid" v-if="['qBittorrent','all'].includes(advanced)"><label>qBittorrent Web UI<input v-model="draft.torrentAddress"/></label><label>{{t('Логин Web UI','Web UI username')}}<input v-model="draft.torrentUser"/></label><label>{{t('Пароль Web UI','Web UI password')}}<input v-model="draft.torrentPassword" type="password" autocomplete="new-password"/></label><label>{{t('Папка загрузок qBittorrent','qBittorrent download folder')}}<input v-model="draft.torrentFolder"/></label></div><div v-if="['Prowlarr','all'].includes(advanced)"><div class="field-grid"><label>Prowlarr URL<input v-model="draft.prowlarrUrl"/></label><label>API key<input v-model="draft.prowlarrKey" type="password" :placeholder="state.config.prowlarrKeySaved?t('Сохранён в Windows','Saved in Windows'):''" autocomplete="new-password"/></label><label>{{t('Индексатор','Indexer')}}<select v-model="draft.indexerId"><option :value="0">{{t('Выберите индексатор','Select indexer')}}</option><option v-for="i in state.indexers||[]" :value="i.id">{{i.name}}</option></select></label></div><div class="actions"><button :disabled="state.busy" @click="action('prowlarr.connect')">{{t('Подключить существующий','Connect existing')}}</button><button :disabled="state.busy" @click="action('indexer.apply')">{{t('Применить к WEB','Apply to WEB')}}</button><button @click="action('prowlarr.open')">{{t('Открыть Prowlarr','Open Prowlarr')}}</button></div></div><div v-if="['FlareSolverr','all'].includes(advanced)" class="checks"><label><input type="checkbox" v-model="draft.installFlare"/>{{t('FlareSolverr для RuTracker','FlareSolverr for RuTracker')}}</label><label><input type="checkbox" v-model="draft.visibleBrowser"/>{{t('Видимый Chromium','Visible Chromium')}}</label><p>{{t('Параметры Windows доступны на Главной. Хранилищами управляйте в WEB. Изменения браузера применяются после безопасного перезапуска.','Windows settings are on Home. Manage storage in WEB. Browser changes apply after a safe restart.')}}</p></div></article></section>
<section v-if="page==='updates'"><div class="heading"><h1>{{t('Обновления','Updates')}}</h1><p>{{t('Проверка службы и приложения на сохранённых приставках','Check service and application on saved consoles')}}</p></div><div class="page-actions"><button :disabled="state.busy" @click="run('updates.check')">⟳ {{t('Проверить обновления','Check updates')}}</button><button class="primary" :disabled="state.busy" @click="run('updates.install',{ids:checked,windows:windowsUpdate})">↓ {{t('Установить обновления','Install updates')}}</button></div><article class="glass update-row"><input type="checkbox" v-model="windowsUpdate"/><img :src="`assets/packageflow-${en?'en':'ru'}.svg`" alt="PackageFlow"/><div><h3>PackageFlow Windows / WEB</h3><p>{{t('Установлена версия','Installed version')}} {{state.version}}</p><p>{{state.windowsUpdate||t('Ещё не проверено','Not checked yet')}}</p></div></article><article v-for="c in consoles" class="glass update-row"><input type="checkbox" :checked="checked.includes(c.id)" @change="mark(c.id)"/><div class="platform">{{c.platform.toUpperCase()}}</div><div><h3>{{c.name}} · {{c.ip}}</h3><p>{{t('Служба и приложение · индивидуальная проверка результата','Service and app · individual result verification')}}</p><p>{{state.updates?.[c.id]?.online?(state.updates[c.id].current||'—'):t('Текущая версия не подтверждена','Current version unconfirmed')}} <span v-if="state.updates?.[c.id]?.target">→ {{state.updates[c.id].target}}</span></p><p v-if="state.updates?.[c.id]?.appTarget">App: {{state.updates[c.id].appTarget}} · {{state.updates[c.id].ready?t('Готова к установке','Ready to install'):t('Готовность не подтверждена','Readiness unconfirmed')}}</p><p v-if="state.updates?.[c.id]?.appCurrent">{{t('Приложение установлено','Installed application')}}: {{state.updates[c.id].appCurrent}}</p><p>{{state.updates?.[c.id]?.message}}</p><p v-if="state.updates?.[c.id]?.flow">{{state.updates[c.id].flow}}</p></div><button :disabled="state.busy" @click="run('console.check',{id:c.id})">{{t('Подробнее','Details')}}</button></article><div class="hint">{{t('Установка проверяет версии, контрольные суммы и подтверждение приставки. Передача байтов не означает завершение установки.','Installation checks versions, checksums and console confirmation. Transferred bytes do not confirm installation.')}}</div></section>
<section v-if="page==='support'"><div class="heading"><h1>{{t('Поддержать проект','Support the project')}}</h1><p>{{t('PackageFlow — бесплатный проект с открытым кодом.','PackageFlow is free and open source.')}}</p><p>{{t('Ваша поддержка помогает развивать приложение и исправлять ошибки. Спасибо, что вы с нами!','Your support helps develop the application and fix bugs. Thank you!')}}</p></div><article v-for="(w,i) in wallets" class="glass wallet"><img :src="`assets/${i===0?'btc':'usdt'}.png`" :alt="w.Name"/><div><h2>{{w.Name}}</h2><p>{{w.Network}}</p><code>{{w.Address}}</code></div><div class="actions"><button @click="qr=w">▦ {{t('Показать QR','Show QR')}}</button><button @click="run('wallet.copy',{index:i})">{{t('Скопировать адрес','Copy address')}}</button></div></article><p class="thanks">♥ {{t('Спасибо за поддержку!','Thank you for your support!')}}</p></section>
</main></div>
<div v-if="error" role="alert" class="error">{{error}}<button @click="error=''">×</button></div><footer v-if="!wizard"><progress v-if="state.busy" :value="state.progress" max="100"/><span :class="{loading:state.busy}">{{state.status||t('PackageFlow · управление','PackageFlow · management')}}</span><details><summary>{{t('Журнал','Activity')}}</summary><div class="log"><p v-for="line in state.log">{{line}}</p></div></details></footer>
<div v-if="dialog" class="overlay" role="dialog" aria-modal="true" :aria-label="dialog.title"><article class="dialog glass"><div class="warning">⚠</div><h2>{{dialog.title}}</h2><p>{{dialog.message}}</p><div class="actions"><button class="primary keep" @click="dialogReply(false)">{{dialog.notice?t('Понятно','OK'):t('Продолжить работу','Continue working')}}</button><button v-if="!dialog.notice" class="danger" @click="dialogReply(true)">{{t('Подтвердить','Confirm')}}</button></div></article></div>
<div v-if="qr" class="overlay" role="dialog" aria-modal="true"><article class="dialog glass qr"><button class="close" @click="qr=null">×</button><h2>{{qr.Name}} · {{qr.Network}}</h2><svg :viewBox="`-4 -4 ${qr.Qr.length+8} ${qr.Qr.length+8}`" shape-rendering="crispEdges"><rect x="-4" y="-4" :width="qr.Qr.length+8" :height="qr.Qr.length+8" fill="white"/><template v-for="(row,y) in qr.Qr"><rect v-for="(cell,x) in row" v-show="cell" :x="x" :y="y" width="1" height="1" fill="black"/></template></svg><code>{{qr.Address}}</code></article></div>
</div>
</template>
